import{d as u,C as e,o as _,c as x,j as i,a as t,E as a,a3 as z}from"./chunks/framework.D4-ViStF.js";const f=JSON.parse('{"title":"庄子·马蹄","description":"残朴以为器，毁道德以为仁义——圣人之过。理解庄子对「善治」的批判。","frontmatter":{"title":"庄子·马蹄","description":"残朴以为器，毁道德以为仁义——圣人之过。理解庄子对「善治」的批判。","category":"guide","aliases":["马蹄","庄子马蹄","zhuangzi chapter 09"],"source":["《庄子·马蹄》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-09.md","filePath":"daoism/zhuang-zi/chapter-09.md","lastUpdated":1788938113000}'),b={name:"daoism/zhuang-zi/chapter-09.md"},w=u({...b,setup(c){const d=[{id:"mati_s1",label:"马……虽有义台路寝，无所用之",sentences:[["马，蹄可以",{text:"践",glossary:"mati_jian"},"霜雪，毛可以",{text:"御",glossary:"mati_yu"},"风寒。"],[{text:"齕",glossary:"mati_he"},"草饮水，",{text:"翘足而陆",glossary:"mati_qiao_lu"},"，此马之真性也。"],["虽有",{text:"义台路寝",glossary:"mati_yitai"},"，",{text:"无所用之",glossary:"mati_wuyong"},"。"]]},{id:"mati_s2",label:"及至伯乐……马之死者十二三矣",sentences:[["及至伯乐，曰：「我",{text:"善",glossary:"mati_shan"},"治马。」"],[{text:"烧之",glossary:"mati_shao"},"，",{text:"剔之",glossary:"mati_ti"},"，",{text:"刻之",glossary:"mati_ke"},"，",{text:"雒之",glossary:"mati_luo"},"。"],[{text:"连之",glossary:"mati_lian"},"以",{text:"羁絷",glossary:"mati_jizhi"},"，",{text:"编之",glossary:"mati_bian"},"以",{text:"皂栈",glossary:"mati_zaozhan"},"，马之死者",{text:"十二三矣",glossary:"mati_shiersan"},"！"]]},{id:"mati_s3",label:"饥之渴之……而马之死者已过半矣",sentences:[[{text:"饥之",glossary:"mati_jishi"},{text:"渴之",glossary:"mati_keshi"},"，",{text:"驰之",glossary:"mati_chishi"},{text:"骤之",glossary:"mati_zhoushi"},"，",{text:"整之",glossary:"mati_zhengshi"},{text:"齐之",glossary:"mati_qishi"},"，"],["前有",{text:"橛饰之患",glossary:"mati_jueshi"},"，而后有",{text:"鞭筴之威",glossary:"mati_biance"},"，而马之死者已过半矣！"]]},{id:"mati_s4",label:"陶者曰……直者应绳",sentences:[[{text:"陶者",glossary:"mati_tao"},"曰：「我善",{text:"治埴",glossary:"mati_zhizhi"},"。」圆者",{text:"中规",glossary:"mati_zhonggui"},"，方者",{text:"中矩",glossary:"mati_zhongju"},"。"],["匠人曰：「我善治木。」曲者",{text:"中钩",glossary:"mati_zhonggou"},"，直者",{text:"应绳",glossary:"mati_yingsheng"},"。"]]},{id:"mati_s5",label:"夫埴木之性……此亦治天下者之过也",sentences:[["夫埴木之性，",{text:"岂欲",glossary:"mati_qiyu"},{text:"中",glossary:"mati_zhong"},"规矩钩绳哉！"],["然且世世称之曰：「伯乐善治马，而陶匠善治埴木。」",{text:"此亦",glossary:"mati_ciyi"},{text:"治",glossary:"mati_zhi"},"天下者之",{text:"过",glossary:"mati_guo"},"也。"]]}],g=[{id:"mati_jian",term:"践",pinyin:"jiàn",meaning:"踩踏。蹄可以践霜雪：马蹄能够踏着霜雪行走。"},{id:"mati_yu",term:"御",pinyin:"yù",meaning:"抵御。毛可以御风寒：马毛能够抵挡风寒。"},{id:"mati_he",term:"齕",pinyin:"hé",meaning:"啃咬。齕草饮水：啃食青草，饮用清水。"},{id:"mati_qiao_lu",term:"翘足而陆",pinyin:"qiáo zú ér lù",meaning:"抬足跳跃。陆通“踛”，指跳跃腾跃；这是马自由舒展的动作。"},{id:"mati_yitai",term:"义台路寝",pinyin:"yì tái lù qǐn",meaning:"华美的高台和宽大的正寝。义台：高台；路寝：正寝、正殿。"},{id:"mati_wuyong",term:"无所用之",pinyin:"wú suǒ yòng zhī",meaning:"对马没有用处。之：指义台路寝。"},{id:"mati_shan",term:"善",pinyin:"shàn",meaning:"擅长、善于。“我善治马”是伯乐自称精于驯治。"},{id:"mati_shao",term:"烧之",pinyin:"shāo zhī",meaning:"用火烧灼马。之：指马；烧，古注多释为烧灼、烙治。"},{id:"mati_ti",term:"剔之",pinyin:"tī zhī",meaning:"剔除、修剪马毛。之：指马。"},{id:"mati_ke",term:"刻之",pinyin:"kè zhī",meaning:"刻削马蹄。之：指马蹄；刻，指修削。"},{id:"mati_luo",term:"雒之",pinyin:"luò zhī",meaning:"烙印马。雒通“烙”，给马打上印记。"},{id:"mati_lian",term:"连之",pinyin:"lián zhī",meaning:"用器具把马连缀、束缚起来。"},{id:"mati_jizhi",term:"羁絷",pinyin:"jī zhí",meaning:"马络头和绊马索。羁：络头；絷：绊索，用来控制马。"},{id:"mati_bian",term:"编之",pinyin:"biān zhī",meaning:"编结、约束马。之：指马；这里承接皂栈，指把马编列圈置其中。"},{id:"mati_zaozhan",term:"皂栈",pinyin:"zào zhàn",meaning:"马槽和马棚。皂：马槽；栈：圈养马的棚栏。"},{id:"mati_shiersan",term:"十二三矣",pinyin:"shí èr sān yǐ",meaning:"十分之二三。马之死者十二三：已有约十分之二三的马死去。"},{id:"mati_jishi",term:"饥之",pinyin:"jī zhī",meaning:"使马饥饿。饥：使动用法，指以饥饿控制马。"},{id:"mati_keshi",term:"渴之",pinyin:"kě zhī",meaning:"使马口渴。渴：使动用法，指以干渴控制马。"},{id:"mati_chishi",term:"驰之",pinyin:"chí zhī",meaning:"使马奔驰。驰：使动用法，指强制马奔跑。"},{id:"mati_zhoushi",term:"骤之",pinyin:"zhòu zhī",meaning:"使马急跑。骤：快速奔跑，指强制马加速。"},{id:"mati_zhengshi",term:"整之",pinyin:"zhěng zhī",meaning:"使马整齐。整：使动用法，指用训练整顿马的动作。"},{id:"mati_qishi",term:"齐之",pinyin:"qí zhī",meaning:"使马划一。齐：使动用法，指使马的动作整齐一致。"},{id:"mati_jueshi",term:"橛饰之患",pinyin:"jué shì zhī huàn",meaning:"马嚼子和装饰带来的祸患。橛：衔在马口中的横木；饰：马具装饰。"},{id:"mati_biance",term:"鞭筴之威",pinyin:"biān cè zhī wēi",meaning:"鞭打与驱赶的威势。筴通“策”，指马鞭。"},{id:"mati_tao",term:"陶者",pinyin:"táo zhě",meaning:"制陶的人。者：……的人。"},{id:"mati_zhizhi",term:"治埴",pinyin:"zhì zhí",meaning:"加工黏土。埴：黏土，读 zhí；治：加工、制作。"},{id:"mati_zhonggui",term:"中规",pinyin:"zhòng guī",meaning:"符合圆规。中：符合、合乎，读 zhòng；规：画圆的工具。"},{id:"mati_zhongju",term:"中矩",pinyin:"zhòng jǔ",meaning:"符合矩尺。中：符合、合乎，读 zhòng；矩：画方的工具。"},{id:"mati_zhonggou",term:"中钩",pinyin:"zhòng gōu",meaning:"符合曲尺。中：符合、合乎，读 zhòng；钩：取曲的工具。"},{id:"mati_yingsheng",term:"应绳",pinyin:"yìng shéng",meaning:"合乎墨线。应：符合；绳：木工取直所用的墨线。"},{id:"mati_qiyu",term:"岂欲",pinyin:"qǐ yù",meaning:"难道想要、哪里愿意。以反问表示埴木本不愿被规矩钩绳强制塑形。"},{id:"mati_zhong",term:"中",pinyin:"zhòng",meaning:"符合、合乎标准。中规矩钩绳：符合规矩钩绳。"},{id:"mati_ciyi",term:"此亦",pinyin:"cǐ yì",meaning:"这也同样是。把治马、治埴木推广到治天下。"},{id:"mati_zhi",term:"治",pinyin:"zhì",meaning:"治理、整治。治天下：以人为标准管理天下。"},{id:"mati_guo",term:"过",pinyin:"guò",meaning:"过失、错误。治天下者之过：治理天下者的过失。"}],y=[{id:"mati2_s1",label:"吾意善治天下者不然",sentences:[["吾",{text:"意",glossary:"mati2_yi"},"善治天下者",{text:"不然",glossary:"mati2_buran"},"。"]]},{id:"mati2_s2",label:"彼民有常性……命曰天放",sentences:[["彼民有",{text:"常性",glossary:"mati2_changxing"},"，织而衣，耕而食，是谓",{text:"同德",glossary:"mati2_tongde"},"。"],[{text:"一而不党",glossary:"mati2_yibudang"},"，",{text:"命曰天放",glossary:"mati2_tianfang"},"。"]]},{id:"mati2_s3",label:"故至德之世……其视颠颠",sentences:[["故",{text:"至德之世",glossary:"mati2_zhideshi"},"，其行",{text:"填填",glossary:"mati2_tiantian"},"，其视",{text:"颠颠",glossary:"mati2_diandian"},"。"]]},{id:"mati2_s4",label:"当是时也……草木遂长",sentences:[[{text:"当是时也",glossary:"mati2_dangshi"},"，山无",{text:"蹊隧",glossary:"mati2_xisui"},"，泽无",{text:"舟梁",glossary:"mati2_zhouliang"},"；"],["万物",{text:"群生",glossary:"mati2_qunsheng"},"，",{text:"连属其乡",glossary:"mati2_lianxiang"},"；"],["禽兽",{text:"成群",glossary:"mati2_chengqun"},"，草木",{text:"遂长",glossary:"mati2_suizhang"},"。"]]},{id:"mati2_s5",label:"是故禽兽可系羁而游……鸟鹊之巢可攀援而窥",sentences:[["是故禽兽可",{text:"系羁而游",glossary:"mati2_xijiyou"},"，鸟鹊之巢可",{text:"攀援而窥",glossary:"mati2_pankui"},"。"]]},{id:"mati2_s6",label:"夫至德之世……恶乎知君子小人哉",sentences:[["夫至德之世，同与禽兽居，族与万物",{text:"并",glossary:"mati2_bing"},"。"],[{text:"恶乎知",glossary:"mati2_wuzhi"},"君子小人哉！"]]},{id:"mati2_s7",label:"同乎无知……素朴而民性得矣",sentences:[["同乎无知，其德不离；同乎无欲，是谓",{text:"素朴",glossary:"mati2_supu"},"。"],["素朴而民性得矣。"]]},{id:"mati2_s8",label:"及至圣人……而天下始分矣",sentences:[["及至圣人，",{text:"蹩躠为仁",glossary:"mati2_biexue"},"，",{text:"踶跂为义",glossary:"mati2_diqi"},"，而天下",{text:"始疑",glossary:"mati2_shiyi"},"矣。"],[{text:"澶漫为乐",glossary:"mati2_chanman"},"，",{text:"摘僻为礼",glossary:"mati2_zhaipi"},"，而天下",{text:"始分",glossary:"mati2_shifen"},"矣。"]]},{id:"mati2_s9",label:"故纯朴不残……孰应六律",sentences:[[{text:"纯朴不残",glossary:"mati2_chunpubucan"},"，孰为",{text:"牺尊",glossary:"mati2_xizun"},"！"],[{text:"白玉不毁",glossary:"mati2_baiyu"},"，孰为",{text:"珪璋",glossary:"mati2_guizhang"},"！"],[{text:"道德不废",glossary:"mati2_daodebufei"},"，",{text:"安取",glossary:"mati2_anqu"},"仁义！"],[{text:"性情不离",glossary:"mati2_xingqing"},"，",{text:"安用",glossary:"mati2_anyong"},"礼乐！"],[{text:"五色不乱",glossary:"mati2_wuse"},"，孰为",{text:"文采",glossary:"mati2_wencai"},"！"],[{text:"五声不乱",glossary:"mati2_wusheng"},"，孰",{text:"应六律",glossary:"mati2_yinglv"},"！"]]}],l=[{id:"mati2_yi",term:"意",pinyin:"yì",meaning:"认为、料想。吾意：我认为。"},{id:"mati2_buran",term:"不然",pinyin:"bù rán",meaning:"不是这样。承接上段“善治”的话题，表示否定前面那种治理方式。"},{id:"mati2_zhideshi",term:"至德之世",pinyin:"zhì dé zhī shì",meaning:"至德充分呈现的时代。至德：德性保持本真；之世：这样的时代。"},{id:"mati2_changxing",term:"常性",pinyin:"cháng xìng",meaning:"恒常、本然的性情。民有常性：百姓有自然固有的生活与性情。"},{id:"mati2_tongde",term:"同德",pinyin:"tóng dé",meaning:"共同处于本真之德。织而衣、耕而食，各循本性，便是同德。"},{id:"mati2_yibudang",term:"一而不党",pinyin:"yī ér bù dǎng",meaning:"浑然一体而不结党分派。一：合一；党：结党、分派。"},{id:"mati2_tianfang",term:"天放",pinyin:"tiān fàng",meaning:"顺应天然、任其自放。不是放纵，而是不以人为标准强制改变本性。"},{id:"mati2_tiantian",term:"填填",pinyin:"tián tián",meaning:"安稳厚重的样子。其行填填：行止安定，不急迫奔竞。"},{id:"mati2_diandian",term:"颠颠",pinyin:"diān diān",meaning:"专一、纯真的样子。其视颠颠：目光专一，不被外物牵引。"},{id:"mati2_dangshi",term:"当是时也",pinyin:"dāng shì shí yě",meaning:"在那个时候。指至德之世，以下开始铺陈其景象。"},{id:"mati2_xisui",term:"蹊隧",pinyin:"xī suì",meaning:"小路和隧道。蹊：山间小径；隧：通道。"},{id:"mati2_zhouliang",term:"舟梁",pinyin:"zhōu liáng",meaning:"船和桥梁。指人为开设的水上交通设施。"},{id:"mati2_qunsheng",term:"群生",pinyin:"qún shēng",meaning:"群聚而生。万物各循其类生息。"},{id:"mati2_chengqun",term:"成群",pinyin:"chéng qún",meaning:"成群结队。禽兽按其本性聚居。"},{id:"mati2_lianxiang",term:"连属其乡",pinyin:"lián shǔ qí xiāng",meaning:"各自相连依附于所居之地。乡：乡土、栖息之处。"},{id:"mati2_suizhang",term:"遂长",pinyin:"suì zhǎng",meaning:"顺遂地生长。遂：顺利、自然。"},{id:"mati2_xijiyou",term:"系羁而游",pinyin:"xì jī ér yóu",meaning:"系着绳索一同游走。人与禽兽之间没有恐惧和伤害。"},{id:"mati2_pankui",term:"攀援而窥",pinyin:"pān yuán ér kuī",meaning:"攀爬上去窥看。援：攀援；窥：探看鸟鹊之巢。"},{id:"mati2_bing",term:"并",pinyin:"bìng",meaning:"并处、并列。族与万物并：人与万物平等共处。"},{id:"mati2_wuzhi",term:"恶乎知",pinyin:"wū hū zhī",meaning:"怎么知道、从哪里知道。反问君子小人的区分从何而来。"},{id:"mati2_supu",term:"素朴",pinyin:"sù pǔ",meaning:"未经染饰和雕琢的本真状态。素：未染；朴：未雕。"},{id:"mati2_biexue",term:"蹩躠为仁",pinyin:"bié sà wéi rén",meaning:"竭尽心力般地推行仁。蹩躠：用力、费力的样子。"},{id:"mati2_diqi",term:"踶跂为义",pinyin:"zhì qí wéi yì",meaning:"踮脚用力般地推行义。踶跂：举足、努力企及的样子。"},{id:"mati2_shiyi",term:"始疑",pinyin:"shǐ yí",meaning:"开始疑惑。圣人推行仁义后，天下由本然的安定转入疑惑。"},{id:"mati2_shifen",term:"始分",pinyin:"shǐ fēn",meaning:"开始分裂、分化。礼乐繁作后，天下出现人为的分别。"},{id:"mati2_chanman",term:"澶漫为乐",pinyin:"chán màn wéi yuè",meaning:"放纵铺张地制作、推行音乐。澶漫：散漫流溢、无所节制。"},{id:"mati2_zhaipi",term:"摘僻为礼",pinyin:"zhāi pì wéi lǐ",meaning:"以琐碎偏执的方式制作、推行礼。摘僻：挑剔偏执。"},{id:"mati2_chunpubucan",term:"纯朴不残",pinyin:"chún pǔ bù cán",meaning:"纯朴不被残害。若本然之朴完整，便无需雕成牺尊。"},{id:"mati2_xizun",term:"牺尊",pinyin:"xī zūn",meaning:"雕成牛形的祭祀酒器。尊：酒器；牺：牛形，读 xī。"},{id:"mati2_baiyu",term:"白玉不毁",pinyin:"bái yù bù huǐ",meaning:"白玉不被雕琢毁损。下句以珪璋说明礼器由本然之物被加工而成。"},{id:"mati2_guizhang",term:"珪璋",pinyin:"guī zhāng",meaning:"古代玉制礼器。珪：玉圭；璋：半圭形玉器。"},{id:"mati2_daodebufei",term:"道德不废",pinyin:"dào dé bù fèi",meaning:"本然的道德不被废弃、损伤。道德完整，便不需要以仁义补救。"},{id:"mati2_anqu",term:"安取",pinyin:"ān qǔ",meaning:"哪里需要取用。道德完整，便无需取用仁义。"},{id:"mati2_anyong",term:"安用",pinyin:"ān yòng",meaning:"哪里需要使用。性情完整，便无需使用礼乐。"},{id:"mati2_xingqing",term:"性情不离",pinyin:"xìng qíng bù lí",meaning:"本性与真情不离散、不失落。"},{id:"mati2_wuse",term:"五色不乱",pinyin:"wǔ sè bù luàn",meaning:"五种基本色不被人为扰乱。五色：青、黄、赤、白、黑。"},{id:"mati2_wencai",term:"文采",pinyin:"wén cǎi",meaning:"人为装饰出的色彩与纹样。五色不乱，便无需另造文采。"},{id:"mati2_wusheng",term:"五声不乱",pinyin:"wǔ shēng bù luàn",meaning:"五种基本音不被人为扰乱。五声：宫、商、角、徵、羽。"},{id:"mati2_yinglv",term:"应六律",pinyin:"yìng liù lǜ",meaning:"应合六律。应：符合；六律：古代音律中的六个阳律。"}],h=[{id:"mati3_s1",label:"夫残朴以为器……圣人之过也",sentences:[["夫",{text:"残朴以为器",glossary:"mati3_canpu"},"，",{text:"工匠之罪",glossary:"mati3_gongzui"},"也；"],[{text:"毁道德",glossary:"mati3_huidaode"},{text:"以为仁义",glossary:"mati3_yiweirenyi"},"，",{text:"圣人之过",glossary:"mati3_shengguo"},"也。"]]},{id:"mati3_s2",label:"夫马陆居则食草饮水……马知已此矣",sentences:[["夫马陆居则食草饮水，喜则",{text:"交颈相靡",glossary:"mati3_jiaojing"},"，怒则",{text:"分背相踢",glossary:"mati3_fenbei"},"。"],["马知已此矣！"]]},{id:"mati3_s3",label:"夫加之以衡扼……伯乐之罪也",sentences:[["夫",{text:"加之以衡扼",glossary:"mati3_henge"},"，",{text:"齐之以月题",glossary:"mati3_yueti"},"，"],["而马知",{text:"介倪",glossary:"mati3_jieni"},{text:"闉扼",glossary:"mati3_yine"},{text:"鸷曼",glossary:"mati3_zhiman"},{text:"诡衔",glossary:"mati3_guixian"},{text:"窃辔",glossary:"mati3_qiepei"},"。"],["故马之知而能",{text:"至盗者",glossary:"mati3_zhidao"},"，伯乐之罪也。"]]},{id:"mati3_s4",label:"夫赫胥氏之时……民能已此矣",sentences:[["夫",{text:"赫胥氏",glossary:"mati3_hexushi"},"之时，民",{text:"居不知所为",glossary:"mati3_juwei"},"，",{text:"行不知所之",glossary:"mati3_xingzhi"},"，"],[{text:"含哺而熙",glossary:"mati3_hanbu"},"，",{text:"鼓腹而游",glossary:"mati3_gufu"},"。"],[{text:"民能已此矣",glossary:"mati3_minyi"},"！"]]},{id:"mati3_s5",label:"及至圣人……此亦圣人之过也",sentences:[["及至圣人，",{text:"屈折礼乐",glossary:"mati3_quzhe"},"以",{text:"匡天下之形",glossary:"mati3_kuangxing"},"，"],[{text:"县跂仁义",glossary:"mati3_xuanqi"},"以",{text:"慰天下之心",glossary:"mati3_weixin"},"，"],["而民乃",{text:"始踶跂好知",glossary:"mati3_shidiqi"},"，",{text:"争归于利",glossary:"mati3_zhengli"},"，",{text:"不可止也",glossary:"mati3_buzhi"},"。"],["此亦",{text:"圣人之过也",glossary:"mati3_shengguo"},"。"]]}],o=[{id:"mati3_canpu",term:"残朴以为器",pinyin:"cán pǔ yǐ wéi qì",meaning:"破坏本然的朴，拿来制成器物。朴：未雕的木材。"},{id:"mati3_gongzui",term:"工匠之罪",pinyin:"gōng jiàng zhī zuì",meaning:"工匠的过错。残朴制器，是以人为技艺伤害本然。"},{id:"mati3_huidaode",term:"毁道德",pinyin:"huǐ dào dé",meaning:"毁坏本然的道与德。这里不是建立仁义，而是先破坏道德。"},{id:"mati3_yiweirenyi",term:"以为仁义",pinyin:"yǐ wéi rén yì",meaning:"拿来制作仁义。以毁坏道德为代价建立人为规范。"},{id:"mati3_shengguo",term:"圣人之过",pinyin:"shèng rén zhī guò",meaning:"圣人的过失。此处批评圣人以仁义礼乐强行改变天下。"},{id:"mati3_jiaojing",term:"交颈相靡",pinyin:"jiāo jǐng xiāng mí",meaning:"相互交颈摩挲。靡：摩擦、亲近；马喜悦时的自然亲昵。"},{id:"mati3_fenbei",term:"分背相踢",pinyin:"fēn bèi xiāng tī",meaning:"背向分开，互相踢打。马发怒时的自然反应。"},{id:"mati3_henge",term:"衡扼",pinyin:"héng è",meaning:"车衡和颈轭。衡：车前横木；扼：套在马颈上的轭。"},{id:"mati3_yueti",term:"月题",pinyin:"yuè tí",meaning:"马额上的月形饰物，也指马络头上的额饰。"},{id:"mati3_jieni",term:"介倪",pinyin:"jiè ní",meaning:"侧目斜视。马受束缚后表现出的不驯与抗拒。"},{id:"mati3_yine",term:"闉扼",pinyin:"yīn è",meaning:"弯曲身体抵抗颈轭。闉：屈曲、弯曲。"},{id:"mati3_zhiman",term:"鸷曼",pinyin:"zhì màn",meaning:"强悍抵触、拖延不进。鸷：强猛；曼：引申为拖延、舒缓。"},{id:"mati3_guixian",term:"诡衔",pinyin:"guǐ xián",meaning:"用诡诈的方式吐弄马嚼子。衔：马口中的嚼子。"},{id:"mati3_qiepei",term:"窃辔",pinyin:"qiè pèi",meaning:"暗中摆脱或咬断缰绳。辔：驾驭牲口的缰绳。"},{id:"mati3_zhidao",term:"至盗者",pinyin:"zhì dào zhě",meaning:"达到像盗贼一样的程度。马被强制治理后，反而发展出诡诈逃脱之知。"},{id:"mati3_hexushi",term:"赫胥氏",pinyin:"hè xū shì",meaning:"传说中的上古帝王，常用来指民性淳朴、无知无欲的时代。"},{id:"mati3_juwei",term:"居不知所为",pinyin:"jū bù zhī suǒ wéi",meaning:"居处时不知要做什么。这里强调无所强为、无机心，不是迷失。"},{id:"mati3_xingzhi",term:"行不知所之",pinyin:"xíng bù zhī suǒ zhī",meaning:"行走时不知要往哪里去。这里强调任其自然，不以外在目标驱迫。"},{id:"mati3_hanbu",term:"含哺而熙",pinyin:"hán bǔ ér xī",meaning:"口含食物而嬉戏。哺：食物；熙：嬉乐、和乐。"},{id:"mati3_gufu",term:"鼓腹而游",pinyin:"gǔ fù ér yóu",meaning:"吃饱后拍着肚子悠游。形容生活满足而无忧无虑。"},{id:"mati3_minyi",term:"民能已此矣",pinyin:"mín néng yǐ cǐ yǐ",meaning:"百姓的本能做到这样就足够了。已此：止于此、仅此而已。"},{id:"mati3_quzhe",term:"屈折礼乐",pinyin:"qū zhé lǐ yuè",meaning:"强行扭曲、折节以推行礼乐。屈折：扭曲、强制。"},{id:"mati3_kuangxing",term:"匡天下之形",pinyin:"kuāng tiān xià zhī xíng",meaning:"矫正天下人的外在形态和行为。匡：矫正、规范。"},{id:"mati3_xuanqi",term:"县跂仁义",pinyin:"xuán qì rén yì",meaning:"高悬仁义，使人踮脚企望。县通“悬”；跂：踮脚。"},{id:"mati3_weixin",term:"慰天下之心",pinyin:"wèi tiān xià zhī xīn",meaning:"安慰、安抚天下人的心。此处反说圣人以仁义控制人心。"},{id:"mati3_shidiqi",term:"始踶跂好知",pinyin:"shǐ zhì qí hào zhī",meaning:"开始踮脚用力，喜好机巧智术。踶跂：努力企及；好知：喜好智巧。"},{id:"mati3_zhengli",term:"争归于利",pinyin:"zhēng guī yú lì",meaning:"争相奔向利益。归：归向、趋向；利：利益。"},{id:"mati3_buzhi",term:"不可止也",pinyin:"bù kě zhǐ yě",meaning:"无法遏止。外在规范一旦激发争利与机巧，便形成自我加速的局面。"}];return(q,n)=>{const p=e("DaoReadingPrelude"),m=e("DaoTextReading"),r=e("DaoKeywordCards"),s=e("DaoLineGuide");return _(),x("div",null,[n[0]||(n[0]=i("h1",{id:"庄子·马蹄",tabindex:"-1"},[t("庄子·马蹄 "),i("a",{class:"header-anchor",href:"#庄子·马蹄","aria-label":'Permalink to "庄子·马蹄"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"篇名释义",tabindex:"-1"},[t("篇名释义 "),i("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),n[2]||(n[2]=i("blockquote",null,[i("p",null,[i("strong",null,"《马蹄》是《庄子》外篇的第二篇，紧承《骈拇》之后。")]),i("p",null,"《骈拇》说：仁义聪明，是骈枝——侈于德。《马蹄》说：伯乐善治马，圣人善治天下——这是罪，这是过。"),i("p",null,"两篇，是同一个命题的两种推进：《骈拇》批判的是「什么」——仁义；《马蹄》批判的是「谁」——善治者·伯乐·圣人。")],-1)),a(p,{title:"从马之真性到含哺而熙，理解庄子对「善治」的批判",summary:"《马蹄》用伯乐治马作比喻，展开外篇「善治」批判的第二个命题：马之真性完整自足，及至伯乐「我善治马」，烧剔刻雒、羁絷皂栈——马之死者过半；民之常性素朴天放，及至圣人屈折礼乐、县跂仁义——天下始疑始分、争归于利不可止。残朴为器，工匠之罪；毁道德为仁义，圣人之过。",points:[{label:"先看",text:"顺着马之真性、至德之世、圣人之过三段，辨认每一次「及至」的转折。"},{label:"再问",text:"庄子说「圣人之过」，是否否定了一切文明？"},{label:"最后",text:"「含哺而熙，鼓腹而游」——你的本性，还需要被「善治」吗？"}],hint:"三次「及至」（及至伯乐·及至圣人·及至圣人），是《马蹄》的叙事骨架——每一次「及至」，都是一次本然状态的终结。"}),n[3]||(n[3]=i("h2",{id:"一、马之真性与善治之过",tabindex:"-1"},[t("一、马之真性与善治之过 "),i("a",{class:"header-anchor",href:"#一、马之真性与善治之过","aria-label":'Permalink to "一、马之真性与善治之过"'},"​")],-1)),n[4]||(n[4]=i("h3",{id:"原文",tabindex:"-1"},[t("原文 "),i("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(m,{sections:d,glossary:g,"default-mode":"classic","aria-label":"马蹄·马之真性 原文"}),n[5]||(n[5]=i("h3",{id:"生僻字词",tabindex:"-1"},[t("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"践",pinyin:["jiàn"],meaning:"踩踏。蹄可以践霜雪：马蹄能够踏着霜雪行走。"},{term:"御",pinyin:["yù"],meaning:"抵御。毛可以御风寒：马毛能够抵挡风寒。"},{term:"齕",pinyin:["hé"],meaning:"啃咬。齕草饮水：啃食青草，饮用清水。"},{term:"翘足而陆",pinyin:["qiáo","zú","ér","lù"],meaning:"抬足跳跃。陆通“踛”，指跳跃腾跃。"},{term:"义台路寝",pinyin:["yì","tái","lù","qǐn"],meaning:"华美的高台和宽大的正寝。"},{term:"无所用之",pinyin:["wú","suǒ","yòng","zhī"],meaning:"对马没有用处。之：指义台路寝。"},{term:"善",pinyin:["shàn"],meaning:"擅长、善于。“我善治马”是伯乐自称精于驯治。"},{term:"烧之",pinyin:["shāo","zhī"],meaning:"用火烧灼马。之：指马。"},{term:"剔之",pinyin:["tī","zhī"],meaning:"剔除、修剪马毛。之：指马。"},{term:"刻之",pinyin:["kè","zhī"],meaning:"刻削马蹄。之：指马蹄。"},{term:"雒之",pinyin:["luò","zhī"],meaning:"烙印马。雒通“烙”，给马打上印记。"},{term:"连之",pinyin:["lián","zhī"],meaning:"把马连缀、束缚起来。"},{term:"羁絷",pinyin:["jī","zhí"],meaning:"马络头和绊马索，用来控制马。"},{term:"编之",pinyin:["biān","zhī"],meaning:"编结、约束马。"},{term:"皂栈",pinyin:["zào","zhàn"],meaning:"马槽和马棚，用来圈养马。"},{term:"十二三矣",pinyin:["shí","èr","sān","yǐ"],meaning:"十分之二三。已有约十分之二三的马死去。"},{term:"饥之",pinyin:["jī","zhī"],meaning:"使马饥饿。饥：使动用法。"},{term:"渴之",pinyin:["kě","zhī"],meaning:"使马口渴。渴：使动用法。"},{term:"驰之",pinyin:["chí","zhī"],meaning:"使马奔驰。驰：使动用法。"},{term:"骤之",pinyin:["zhòu","zhī"],meaning:"使马急跑。骤：快速奔跑。"},{term:"整之",pinyin:["zhěng","zhī"],meaning:"使马整齐。"},{term:"齐之",pinyin:["qí","zhī"],meaning:"使马划一。"},{term:"橛饰之患",pinyin:["jué","shì","zhī","huàn"],meaning:"马嚼子和装饰带来的祸患。"},{term:"鞭筴之威",pinyin:["biān","cè","zhī","wēi"],meaning:"鞭打与驱赶的威势。筴通“策”，指马鞭。"},{term:"陶者",pinyin:["táo","zhě"],meaning:"制陶的人。"},{term:"治埴",pinyin:["zhì","zhí"],meaning:"加工黏土。埴：黏土。"},{term:"中规",pinyin:["zhòng","guī"],meaning:"符合圆规。中：符合，读 zhòng。"},{term:"中矩",pinyin:["zhòng","jǔ"],meaning:"符合矩尺。中：符合，读 zhòng。"},{term:"中钩",pinyin:["zhòng","gōu"],meaning:"符合曲尺。中：符合，读 zhòng。"},{term:"应绳",pinyin:["yìng","shéng"],meaning:"合乎墨线。"},{term:"岂欲",pinyin:["qǐ","yù"],meaning:"难道想要、哪里愿意。"},{term:"中",pinyin:["zhòng"],meaning:"符合、合乎标准。"},{term:"此亦",pinyin:["cǐ","yì"],meaning:"这也同样是。"},{term:"治",pinyin:["zhì"],meaning:"治理、整治。治天下：以人为标准管理天下。"},{term:"过",pinyin:["guò"],meaning:"过失、错误。"}]}),n[6]||(n[6]=i("h3",{id:"核心句引读",tabindex:"-1"},[t("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"马之真性，完整自足——及至伯乐，一切开始改变",subtitle:"用人的标准来「善治」马——这本身，就是问题的起点。",lines:[{text:"马，蹄可以践霜雪，毛可以御风寒。齕草饮水，翘足而陆，此马之真性也。虽有义台路寝，无所用之。",tone:"真性",guide:"《马蹄》开篇，庄子用极简洁的笔墨，描绘了马的真性——四句话，四个维度：蹄可以践霜雪（马蹄，天生就能踩踏霜雪）、毛可以御风寒（马毛，天生就能抵御风寒）、齕草饮水（啃草喝水，自给自足）、翘足而陆（昂首翘足，纵跳腾跃）。此马之真性也——这四句，描绘的是马在自然状态下的完整生命——不需要任何人来「帮助」它，不需要任何工具来「改善」它——它本来就是完整的、自足的。紧接着，庄子轻轻补了一句：「虽有义台路寝，无所用之。」义台路寝——华美的台榭、宏伟的宫室——这是人类文明的成就，是人类认为「好」的东西——但对马来说，无所用之——没有任何用处。这一句，看似轻描淡写，实则是全篇最深的预设：人类用「好」的标准来衡量马——但马有自己的「好」——马的「好」，是践霜雪、御风寒、齕草饮水、翘足而陆——不是义台路寝。用人的标准来「善治」马——这本身，就是问题的起点。"},{text:"及至伯乐，曰：我善治马。烧之，剔之，刻之，雒之。连之以羁絷，编之以皂栈，马之死者十二三矣！",tone:"伯乐",guide:"「及至伯乐」——等到伯乐出现——这两个字，是《马蹄》全篇的第一个转折标志：马的真性，本来是完整的——「及至伯乐」——一切开始改变。「我善治马」——注意：伯乐说的是「善」治——不是恶意的，不是破坏性的——是「善意的治」，是「好的治」。庄子要批判的，不是恶意的破坏，而是善意的治理——正是这个「善」，才是最深的问题所在。伯乐的「善治」，分两个阶段展开——第一阶段·改造身体：烧（用火烙烫马蹄）、剔（剃除马毛）、刻（刻削蹄甲）、雒（烙印记号）——每一个动作，都直接对应马的一项真性。再加上羁絷皂栈——络头绊索、马槽马棚——束缚自由，圈养空间——马之死者十二三矣——还没有开始正式「使用」，马就已经死了十分之二三。"},{text:"饥之渴之，驰之骤之，整之齐之，前有橛饰之患，而后有鞭筴之威，而马之死者已过半矣！",tone:"过半",guide:"第二阶段·训练使用：饥之渴之（用饥渴控制马）、驰之骤之（强制奔跑训练）、整之齐之（训练整齐队列）、前有橛饰束缚、后有鞭筴威胁——马之死者已过半矣——马，已经死了超过一半。两个阶段，两个数字——从十二三，到过半——「善治」越深入，死亡越多。这不是意外，这是必然：马蹄，天生可以践霜雪——烧之；马毛，天生可以御风寒——剔之；自由奔跑——驰之骤之；自然栖息——编之以皂栈。马的每一项真性，都有一项「善治」与之对应——每一项「善治」，都是对那项真性的直接破坏。伯乐不是在「治」马——伯乐是在把马，从「马」变成「工具」。"},{text:"夫埴木之性，岂欲中规矩钩绳哉！然且世世称之曰：伯乐善治马，而陶匠善治埴木。此亦治天下者之过也。",tone:"反问",guide:"庄子把伯乐的逻辑，推广到陶匠与木匠——陶匠「我善治埴」：圆的符合圆规，方的符合方尺——把黏土，做成规矩的形状；木匠「我善治木」：弯曲的符合曲尺，笔直的符合墨线——把木材，做成规整的形状。三者，是同一个逻辑：都是用外在的标准（规矩钩绳），来改造对象的天然状态。庄子的反问，是全段的核心：「夫埴木之性，岂欲中规矩钩绳哉！」黏土与木材的本性，难道想要符合规矩钩绳的标准吗？本性，从来不「欲」被外在标准所规范——「欲」，是外在强加的，不是本性自然的。然而——「然且世世称之曰」——世世代代，都在称赞他们「善治」。这是第一段最深的一击：称赞「善治」，就是在确立「善治」的合法性——就是在告诉天下：改造本性，是对的；用外在标准规范本性，是好的。「此亦治天下者之过也」——这，也是治天下者的过失。「亦」——也——暗示了一个未说出口的前提：治天下者，还有更多的过——称赞善治，只是其中之一。"}]}),n[7]||(n[7]=i("h2",{id:"二、至德之世",tabindex:"-1"},[t("二、至德之世 "),i("a",{class:"header-anchor",href:"#二、至德之世","aria-label":'Permalink to "二、至德之世"'},"​")],-1)),n[8]||(n[8]=i("h3",{id:"原文-1",tabindex:"-1"},[t("原文 "),i("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(m,{sections:y,glossary:l,"default-mode":"classic","aria-label":"马蹄·至德之世 原文"}),n[9]||(n[9]=i("h3",{id:"生僻字词-1",tabindex:"-1"},[t("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"意",pinyin:["yì"],meaning:"认为、料想。吾意：我认为。"},{term:"不然",pinyin:["bù","rán"],meaning:"不是这样。承接上段，否定伯乐式的“善治”。"},{term:"常性",pinyin:["cháng","xìng"],meaning:"恒常、本然的性情。民有常性：百姓有自然固有的生活与性情。"},{term:"同德",pinyin:["tóng","dé"],meaning:"共同处于本真之德。各循本性而生活，便是同德。"},{term:"一而不党",pinyin:["yī","ér","bù","dǎng"],meaning:"浑然一体而不结党分派。"},{term:"天放",pinyin:["tiān","fàng"],meaning:"顺应天然，任其自放，不以人为标准强制改变本性。"},{term:"至德之世",pinyin:["zhì","dé","zhī","shì"],meaning:"至德充分呈现的时代，人的性情保持本真。"},{term:"填填",pinyin:["tián","tián"],meaning:"安稳厚重的样子。其行填填：行止安定，不急迫奔竞。"},{term:"颠颠",pinyin:["diān","diān"],meaning:"专一纯真的样子。其视颠颠：目光不被外物牵引。"},{term:"蹊隧",pinyin:["xī","suì"],meaning:"山间小路和隧道。指人为开凿的通道。"},{term:"舟梁",pinyin:["zhōu","liáng"],meaning:"船和桥梁，指人为设置的水上交通设施。"},{term:"群生",pinyin:["qún","shēng"],meaning:"群聚而生。万物各循其类生息。"},{term:"连属其乡",pinyin:["lián","shǔ","qí","xiāng"],meaning:"相连依附于各自的乡土、栖息之处。"},{term:"成群",pinyin:["chéng","qún"],meaning:"成群结队。禽兽按其本性聚居。"},{term:"遂长",pinyin:["suì","zhǎng"],meaning:"顺遂地生长。遂：顺利、自然。"},{term:"系羁而游",pinyin:["xì","jī","ér","yóu"],meaning:"系着绳索一同游走。人与禽兽之间没有恐惧和伤害。"},{term:"攀援而窥",pinyin:["pān","yuán","ér","kuī"],meaning:"攀爬上去窥看鸟鹊之巢。"},{term:"并",pinyin:["bìng"],meaning:"并处、并列。族与万物并：人与万物平等共处。"},{term:"恶乎知",pinyin:["wū","hū","zhī"],meaning:"怎么知道、从哪里知道。反问君子小人的区分。"},{term:"素朴",pinyin:["sù","pǔ"],meaning:"未经染饰和雕琢的本真状态。"},{term:"蹩躠为仁",pinyin:["bié","sà","wéi","rén"],meaning:"竭尽心力般地推行仁。蹩躠：用力、费力的样子。"},{term:"踶跂为义",pinyin:["zhì","qí","wéi","yì"],meaning:"踮脚用力般地推行义。踶跂：努力企及的样子。"},{term:"始疑",pinyin:["shǐ","yí"],meaning:"开始疑惑。圣人推行仁义后，天下由安定转入疑惑。"},{term:"澶漫为乐",pinyin:["chán","màn","wéi","yuè"],meaning:"放纵铺张地推行音乐。澶漫：流溢而无所节制。"},{term:"摘僻为礼",pinyin:["zhāi","pì","wéi","lǐ"],meaning:"以琐碎偏执的方式推行礼。摘僻：挑剔偏执。"},{term:"始分",pinyin:["shǐ","fēn"],meaning:"开始分裂、分化。礼乐繁作后，天下出现人为分别。"},{term:"纯朴不残",pinyin:["chún","pǔ","bù","cán"],meaning:"纯朴不被残害。若本然之朴完整，便无需雕成牺尊。"},{term:"牺尊",pinyin:["xī","zūn"],meaning:"雕成牛形的祭祀酒器。"},{term:"白玉不毁",pinyin:["bái","yù","bù","huǐ"],meaning:"白玉不被雕琢毁损。"},{term:"珪璋",pinyin:["guī","zhāng"],meaning:"古代玉制礼器。珪为玉圭，璋为半圭形玉器。"},{term:"道德不废",pinyin:["dào","dé","bù","fèi"],meaning:"本然的道与德不被废弃、损伤。"},{term:"安取",pinyin:["ān","qǔ"],meaning:"哪里需要取用。道德完整，便无需取用仁义。"},{term:"性情不离",pinyin:["xìng","qíng","bù","lí"],meaning:"本性与真情不离散、不失落。"},{term:"安用",pinyin:["ān","yòng"],meaning:"哪里需要使用。性情完整，便无需使用礼乐。"},{term:"五色不乱",pinyin:["wǔ","sè","bù","luàn"],meaning:"五种基本色不被人为扰乱。"},{term:"文采",pinyin:["wén","cǎi"],meaning:"人为装饰出的色彩与纹样。"},{term:"五声不乱",pinyin:["wǔ","shēng","bù","luàn"],meaning:"五种基本音不被人为扰乱。"},{term:"应六律",pinyin:["yìng","liù","lǜ"],meaning:"应合六律。应：符合；六律：古代音律中的六个阳律。"}]}),n[10]||(n[10]=i("h3",{id:"核心句引读-1",tabindex:"-1"},[t("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"天放·素朴——民性得矣",subtitle:"天放，是让本性自然流淌，不用任何外在标准来引导它、规范它、「改善」它。",lines:[{text:"吾意善治天下者不然。彼民有常性，织而衣，耕而食，是谓同德。一而不党，命曰天放。",tone:"天放",guide:"第一段批判了伯乐、陶匠、匠人的「善治」，第二段庄子以第一人称转入正论——「吾意」——依我看——真正善于治理天下的，不是那样做的。这一句，是第二段的总纲。庄子不是在说「不治」，而是在说「不那样治」——那么，真正的「善治天下」，是什么样的？民有常性——百姓，有自己恒常的本性——织而衣，耕而食——织布而穿衣，耕田而饮食——自给自足，不依赖任何外在的制度或规范。是谓同德——这，叫做「同德」。一而不党，命曰天放——浑然一体，不结党，不分派——没有「我们」与「他们」，没有派系，没有对立——这，称之为「天放」。「天放」，是《马蹄》全篇最重要的概念：不是放纵，不是无序——而是天然地放任本性自由生长，不加干涉，不加规范，不加「善治」。"},{text:"故至德之世，其行填填，其视颠颠。……禽兽可系羁而游，鸟鹊之巢可攀援而窥。",tone:"至德",guide:"庄子由「天放」的定义，展开至德之世的具体图景——其行填填，其视颠颠——两个叠词，描绘的是那个时代的人：行走，安稳踏实——不慌张，不急迫，不为任何目的奔命；目光，专注直视——不左顾右盼，不觊觎，不比较。这两个叠词，描绘的是一种内在的安定——因为本性没有被扰动，所以安定。接下来六个短句，描绘至德之世的自然状态：山无蹊隧（山中没有人工开凿的道路与隧道——人，不需要征服山）、泽无舟梁（水泽中没有船只与桥梁——人，不需要征服水）、万物群生连属其乡、禽兽成群草木遂长——没有人去「管理」它们，它们反而更好。然后是至德之世最动人的两个细节——禽兽可系羁而游（禽兽，可以用绳索牵着一起游玩——不是因为禽兽被驯服了，而是因为人与禽兽之间，没有恐惧，没有对立）、鸟鹊之巢可攀援而窥（鸟鹊的巢，可以攀爬上去探看——不是因为鸟鹊失去了警觉，而是因为人与鸟鹊之间，没有威胁，没有伤害）。这两个细节，描绘的不是人统治自然，而是人与自然之间，那种本然的亲密与信任——一旦人开始「善治」，它就消失了。"},{text:"同乎无知，其德不离；同乎无欲，是谓素朴。素朴而民性得矣。",tone:"素朴",guide:"庄子将图景收束，深入到至德之世的内在本质——同与禽兽居，族与万物并（与禽兽同居，与万物并列——不是说人退化为动物，而是说：人，没有把自己凌驾于万物之上）。恶乎知君子小人哉（至德之世，没有君子小人之分——不是因为所有人都一样，而是因为没有人用「君子小人」这套标准来衡量人——这套标准，本身就是「善治」的产物）。同乎无知，其德不离——同样处于无知的状态——这里的「无知」，不是愚昧，不是蒙昧——而是无机心之知——没有那种算计的、比较的、追名逐利的「知」——本真之德，不离散，不失去。同乎无欲，是谓素朴——同样处于无欲的状态——不是没有感受，不是麻木——而是无贪欲——没有那种占有的、攀比的、永不满足的「欲」——这，叫做素朴。「素朴」——素：未染色的丝——天然的颜色；朴：未加工的木——天然的形状——素朴，就是未经雕琢的自然本真状态——没有被仁义染色，没有被礼乐加工——保持着天然的颜色与形状。素朴而民性得矣——保持素朴，百姓的本性就得以保全。"},{text:"故纯朴不残，孰为牺尊！白玉不毁，孰为珪璋！道德不废，安取仁义！性情不离，安用礼乐！五色不乱，孰为文采！五声不乱，孰应六律！",tone:"六反问",guide:"六句排比，六个反问，是《马蹄》全篇最精彩的段落——结构完全一致：本然状态不被破坏 → 哪里需要人工产物？纯朴不残，孰为牺尊（浑然完整的木材，如果不被破坏，谁会去雕刻成牺尊？牺尊越精美，意味着纯朴被残得越深）；白玉不毁，孰为珪璋；道德不废，安取仁义（这是六句中最核心的一句：道德，如果不被废弃破坏——哪里需要取用仁义？仁义，是道德被废弃之后的替代品——有了仁义，就意味着道德已经废弃）；性情不离，安用礼乐；五色不乱，孰为文采；五声不乱，孰应六律。六句，共同指向一个逻辑：本然状态（完整·自足·无需外物）→ 被破坏 → 人工产物（补救·替代·外在标准）→ 被称赞为「善」→ 本然状态，永远消失。人工产物越精美，意味着本然状态被破坏得越彻底——牺尊越精美，纯朴被残得越深；仁义越完善，道德被废得越彻底。这是《马蹄》对文明最深的批判逻辑：文明的每一项成就，都是以本然状态的破坏为代价的——成就越高，代价越大。"}]}),n[11]||(n[11]=i("h2",{id:"三、圣人之过",tabindex:"-1"},[t("三、圣人之过 "),i("a",{class:"header-anchor",href:"#三、圣人之过","aria-label":'Permalink to "三、圣人之过"'},"​")],-1)),n[12]||(n[12]=i("h3",{id:"原文-2",tabindex:"-1"},[t("原文 "),i("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(m,{sections:h,glossary:o,"default-mode":"classic","aria-label":"马蹄·圣人之过 原文"}),n[13]||(n[13]=i("h3",{id:"生僻字词-2",tabindex:"-1"},[t("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"残朴以为器",pinyin:["cán","pǔ","yǐ","wéi","qì"],meaning:"残：残损、破坏；朴：未加工的原木。破坏原木来制作器具。"},{term:"工匠之罪",pinyin:["gōng","jiàng","zhī","zuì"],meaning:"工匠的罪过。"},{term:"毁道德",pinyin:["huǐ","dào","dé"],meaning:"毁坏本然的道与德。这里不是建立仁义，而是先破坏道德。"},{term:"以为仁义",pinyin:["yǐ","wéi","rén","yì"],meaning:"拿来制作仁义，以毁坏道德为代价建立人为规范。"},{term:"圣人之过",pinyin:["shèng","rén","zhī","guò"],meaning:"圣人的过失。"},{term:"交颈相靡",pinyin:["jiāo","jǐng","xiāng","mí"],meaning:"交颈：颈部相交；靡：依偎、摩挲。高兴时互相依偎摩挲。"},{term:"分背相踢",pinyin:["fēn","bèi","xiāng","tī"],meaning:"分背：背对背分开；踢：踢踹。愤怒时背对背互相踢踹。"},{term:"衡扼",pinyin:["héng","è"],meaning:"衡：车衡，驾车的横木；扼：套在马颈上的轭。"},{term:"月题",pinyin:["yuè","tí"],meaning:"马额头上的月形装饰（马络头上的饰件）。"},{term:"介倪",pinyin:["jiè","ní"],meaning:"斜眼侧视（表示不驯服）。"},{term:"闉扼",pinyin:["yīn","è"],meaning:"弯曲身体抵抗颈轭。"},{term:"鸷曼",pinyin:["zhì","màn"],meaning:"凶猛抵触、拖延拖拽。"},{term:"诡衔",pinyin:["guǐ","xián"],meaning:"用诡诈的方式对付嚼子（吐衔）。"},{term:"窃辔",pinyin:["qiè","pèi"],meaning:"辔：缰绳。暗中咬断缰绳。"},{term:"至盗者",pinyin:["zhì","dào","zhě"],meaning:"达到像盗贼一样的程度。马被强制治理后，反而发展出诡诈逃脱之知。"},{term:"赫胥氏",pinyin:["hè","xū","shì"],meaning:"传说中上古时代的帝王，象征最本然的时代。"},{term:"居不知所为",pinyin:["jū","bù","zhī","suǒ","wéi"],meaning:"居处时不知要做什么，强调无所强为、无机心，不是迷失。"},{term:"行不知所之",pinyin:["xíng","bù","zhī","suǒ","zhī"],meaning:"行走时不知要往哪里去，强调任其自然，不以外在目标驱迫。"},{term:"含哺而熙",pinyin:["hán","bǔ","ér","xī"],meaning:"含哺：口含食物；熙：嬉戏、欢乐。口含食物嬉戏玩乐。"},{term:"鼓腹而游",pinyin:["gǔ","fù","ér","yóu"],meaning:"鼓腹：拍打肚子（吃饱的满足感）。拍着肚子悠游自在。"},{term:"民能已此矣",pinyin:["mín","néng","yǐ","cǐ","yǐ"],meaning:"百姓的本然能力做到这样就足够了。已此：止于此、仅此而已。"},{term:"屈折礼乐",pinyin:["qū","zhé","lǐ","yuè"],meaning:"屈折：扭曲、强迫。强行用礼乐扭曲天下人的形体与行为。"},{term:"匡天下之形",pinyin:["kuāng","tiān","xià","zhī","xíng"],meaning:"矫正天下人的外在形态和行为。匡：矫正、规范。"},{term:"县跂仁义",pinyin:["xuán","qì","rén","yì"],meaning:"高悬仁义，使人踮脚企望。县通“悬”；跂：踮脚。"},{term:"慰天下之心",pinyin:["wèi","tiān","xià","zhī","xīn"],meaning:"安慰、安抚天下人的心。此处反说圣人以仁义控制人心。"},{term:"始踶跂好知",pinyin:["shǐ","zhì","qí","hào","zhī"],meaning:"开始踮脚用力，喜好机巧智术。踶跂：努力企及；好知：喜好智巧。"},{term:"争归于利",pinyin:["zhēng","guī","yú","lì"],meaning:"争相奔向利益。归：归向、趋向；利：利益。"},{term:"不可止也",pinyin:["bù","kě","zhǐ","yě"],meaning:"无法遏止。外在规范一旦激发争利与机巧，便形成自我加速的局面。"}]}),n[14]||(n[14]=i("h3",{id:"核心句引读-2",tabindex:"-1"},[t("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"残朴为器，工匠之罪；毁道德为仁义，圣人之过",subtitle:"善意，不能成为「治」的免责理由。",lines:[{text:"夫残朴以为器，工匠之罪也；毁道德以为仁义，圣人之过也。",tone:"定性",guide:"第三段开篇，两句极简洁的对仗——是第一段与第二段的直接收束，也是全篇的定性宣判：第一段说陶匠善治埴、匠人善治木——第三段说：残朴以为器，工匠之罪也；第二段说圣人蹩躠为仁、踶跂为义——第三段说：毁道德以为仁义，圣人之过也。「罪」与「过」——罪，是明确的罪行；过，是过失、错误——庄子用「过」而非「罪」来定性圣人，并非是在减轻圣人的责任——而是在说：圣人毁道德以为仁义，不是出于恶意（所以不用「罪」），而是出于善意的错误（所以用「过」）——但善意的错误，造成的伤害，不比恶意的罪行轻。"},{text:"夫马陆居则食草饮水，喜则交颈相靡，怒则分背相踢。马知已此矣！夫加之以衡扼，齐之以月题，而马知介倪闉扼鸷曼诡衔窃辔。故马之知而能至盗者，伯乐之罪也。",tone:"异化",guide:"定性之后，庄子再次回到马——但这一次，描绘的不是马的「真性」，而是马的「真知」，以及真知被异化之后的结果。马陆居则食草饮水，喜则交颈相靡，怒则分背相踢——四句话，是马在自然状态下的完整情感与本能——马知已此矣——马的「知」（本能与情感），到此为止——仅此而已。这一句，与第二段「民能已此矣」遥相呼应——「已此」——仅此——不是在说马很笨，不是在贬低马——而是在说：马的知，是完整的、自足的——喜怒饮食，已经是马全部的知——不需要更多，也不应该更多。然而——加之以衡扼，齐之以月题——给马套上车衡与颈轭，用月形装饰约束马头——这是伯乐「善治」之后的马的处境——而马知介倪闉扼鸷曼诡衔窃辔——马，学会了五种新的「知」：介倪（斜眼侧视，表示不驯）、闉扼（弯曲身体，抵抗颈轭）、鸷曼（凶猛抵触，拖延拖拽）、诡衔（诡诈地对付嚼子）、窃辔（暗中咬断缰绳）。这五种行为，是马在被「善治」之后发展出来的「新知」——但这个「新知」，是反抗、是欺骗、是盗窃——马，从「食草饮水·交颈相靡·分背相踢」，变成了「介倪·闉扼·鸷曼·诡衔·窃辔」——从自然的本能，变成了对抗束缚的技巧——从素朴的情感，变成了诡诈的手段。故马之知而能至盗者，伯乐之罪也——马的知，发展到能做出盗窃般行为的程度——这，是伯乐的罪。「善治」的代价，不只是死亡——还有异化：被「善治」的，即使活下来，也不再是原来的自己——而是一个被扭曲、被异化的自己。"},{text:"夫赫胥氏之时，民居不知所为，行不知所之，含哺而熙，鼓腹而游。民能已此矣！",tone:"含哺",guide:"马的异化，是对人的异化的预演——庄子将笔锋转向人，召唤出赫胥氏——传说中上古最本然时代的象征——民居不知所为，行不知所之（百姓居处，不知道该做什么；行走，不知道该去哪里——不是因为愚昧，而是因为无为——不是因为迷失，而是因为随性——本性自足，不需要「做」什么，不需要「去」哪里），含哺而熙，鼓腹而游（口含食物，嬉戏玩乐；拍着肚子，悠游自在——吃，是自然的；乐，是自然的——满足，不需要理由，不需要目的）。民能已此矣——百姓的「能」（本能），到此为止——仅此而已。与「马知已此矣」完全对应：马的知，仅此而已；民的能，仅此而已——「已此」，不是贫乏，不是不足，而是恰好：本性所需，恰好如此。「含哺而熙，鼓腹而游」——这八个字，是《马蹄》对「至德之世」最生动的描绘——比第二段的「填填颠颠」更具体，更温暖，更有画面感：一个孩子，嘴里含着食物，笑着跑来跑去；一个老人，拍着肚子，在田间悠游——没有仁义，没有礼乐，没有君子小人——只有含哺而熙，鼓腹而游。"},{text:"及至圣人，屈折礼乐以匡天下之形，县跂仁义以慰天下之心，而民乃始踶跂好知，争归于利，不可止也。此亦圣人之过也。",tone:"圣人之过",guide:"然后，是第三次「及至」——及至圣人，屈折礼乐以匡天下之形（强行用礼乐扭曲天下人的外在形态——坐要有坐相，站要有站相——把人的外在，纳入礼乐的框架），县跂仁义以慰天下之心（高悬仁义，让天下人踮脚企及，以此来「安慰」天下人的心——「县跂」——高悬，让人踮脚——这个意象极为精准：仁义，被高悬在那里——高到让人需要踮脚才能够到——圣人说：这是为了安慰你们的心。但庄子说：这不是安慰，这是折磨——让人永远踮着脚，永远够不到——不是安慰，是制造永恒的焦虑）。而民乃始踶跂好知，争归于利，不可止也——踶跂好知（踮脚努力，喜好机巧之知），争归于利（争相追逐利益），不可止也（无法停止）。这与马的「介倪闉扼鸷曼诡衔窃辔」完全对应——马被套上衡扼，学会了诡衔窃辔——民被套上礼乐仁义，学会了踶跂好知、争归于利——两者，是同一个逻辑，同一个悲剧。「不可止也」——这三个字，是《马蹄》最深的悲哀：一旦圣人用礼乐匡形、用仁义县跂——民的踶跂好知、争归于利，就再也停不下来了——因为本性已经被改变，素朴已经失去，赫胥氏之时，一去不返。此亦圣人之过也——《马蹄》全篇，以这一句作结。「亦」——也——这个字，与第一段结尾「此亦治天下者之过也」前后呼应：两个「亦」，暗示了一个未说出口的前提：圣人，还有更多的过——这里说的，只是其中之一。「圣人之过」——这四个字，是《马蹄》对儒家最直接的批判——儒家最推崇的，是圣人——尧、舜、禹、汤、文、武、周公——这些圣人，是儒家道德体系的基石。庄子说：圣人，是天下失去素朴的根源——圣人，有过。"}]}),n[15]||(n[15]=z("",35))])}}});export{f as __pageData,w as default};
